const cfgIn = $input.first().json;
const body = (cfgIn.body && typeof cfgIn.body === 'object') ? cfgIn.body : {};

const defaults = {
  requestId: 'LLM-' + Date.now(),
  systemPrompt: 'You are a support-ticket triage assistant. Respond with ONLY a JSON object, no prose and no markdown fences.',
  prompt: 'Classify this ticket and return category, priority and a one-sentence summary. Ticket: "My invoice for March shows two charges for the same subscription and I need one refunded urgently."',
  expectJson: true,
  schema: { category: 'enum:billing|technical|account|other', priority: 'enum:low|medium|high|urgent', summary: 'string' },
  maxTokens: 1024,
  temperature: 0.2,
  preferredProvider: '',
  minChars: 2,
  maxChars: 8000,
  mustContain: [],
  mustNotContain: []
};

const req = { ...defaults, ...body };
req.requestId = String(req.requestId);
req.prompt = String(req.prompt || defaults.prompt);
req.systemPrompt = String(req.systemPrompt || defaults.systemPrompt);
req.expectJson = (req.expectJson === true || req.expectJson === 'true');
req.maxTokens = Math.max(16, Number(req.maxTokens) || defaults.maxTokens);
const t = Number(req.temperature);
req.temperature = Number.isFinite(t) ? Math.min(Math.max(t, 0), 1) : defaults.temperature;
req.minChars = Math.max(0, Number(req.minChars) || 0);
req.maxChars = Number(req.maxChars) > 0 ? Number(req.maxChars) : defaults.maxChars;
if (!req.schema || typeof req.schema !== 'object' || Array.isArray(req.schema)) req.schema = {};
['mustContain', 'mustNotContain'].forEach(k => {
  req[k] = Array.isArray(req[k]) ? req[k].map(String) : [];
});

// cyrb53 hash: stable key for the stale-cache fallback
function cyrb53(str, seed = 0) {
  let h1 = 0xdeadbeef ^ seed, h2 = 0x41c6ce57 ^ seed;
  for (let i = 0; i < str.length; i++) {
    const ch = str.charCodeAt(i);
    h1 = Math.imul(h1 ^ ch, 2654435761);
    h2 = Math.imul(h2 ^ ch, 1597334677);
  }
  h1 = Math.imul(h1 ^ (h1 >>> 16), 2246822507) ^ Math.imul(h2 ^ (h2 >>> 13), 3266489909);
  h2 = Math.imul(h2 ^ (h2 >>> 16), 2246822507) ^ Math.imul(h1 ^ (h1 >>> 13), 3266489909);
  return (4294967296 * (2097151 & h2) + (h1 >>> 0)).toString(16);
}
const promptHash = cyrb53(req.systemPrompt + '\n' + req.prompt + '\n' + req.expectJson);

const config = {
  providerOrder: String(cfgIn.providerOrder || '').split(',').map(s => s.trim().toLowerCase()).filter(Boolean),
  models: { anthropic: cfgIn.anthropicModel, openai: cfgIn.openaiModel, gemini: cfgIn.geminiModel },
  maxAttemptsPerProvider: Math.max(1, Number(cfgIn.maxAttemptsPerProvider) || 2),
  requestTimeoutMs: Number(cfgIn.requestTimeoutMs) || 30000,
  backoffBaseSeconds: Number(cfgIn.backoffBaseSeconds) || 2,
  maxBackoffSeconds: Number(cfgIn.maxBackoffSeconds) || 20,
  breakerFailureThreshold: Math.max(1, Number(cfgIn.breakerFailureThreshold) || 3),
  breakerCooldownMinutes: Math.max(1, Number(cfgIn.breakerCooldownMinutes) || 5),
  staleCacheMaxHours: Math.max(1, Number(cfgIn.staleCacheMaxHours) || 72),
  rejectRefusals: cfgIn.rejectRefusals === true,
  slackChannel: cfgIn.slackChannel,
  degradedMessage: cfgIn.degradedMessage
};

return [{ json: { request: req, promptHash, config, startedAt: Date.now() } }];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const base = ref('JS - Normalize Request');
const rows = $input.all().map(i => i.json).filter(r => r && r.provider);
const { request: req, config } = base;
const KNOWN = ['anthropic', 'openai', 'gemini'];

let order = config.providerOrder.filter(p => KNOWN.includes(p));
if (!order.length) order = [...KNOWN];
const pref = String(req.preferredProvider || '').toLowerCase();
if (pref && order.includes(pref)) order = [pref, ...order.filter(p => p !== pref)];

const now = Date.now();
const health = {};
rows.forEach(r => { health[r.provider] = r; });

// Circuit breaker: skip providers whose circuit is still open
const skipped = [];
let chain = [];
for (const p of order) {
  const h = health[p];
  const openUntil = h && h.circuit_open_until ? new Date(h.circuit_open_until).getTime() : 0;
  if (openUntil > now) {
    skipped.push({ provider: p, reason: 'circuit_open', openUntil: new Date(openUntil).toISOString(), lastError: h.last_error || null });
  } else {
    chain.push({ provider: p, model: config.models[p] });
  }
}

// If every circuit is open, try them all anyway instead of failing without a single call
let allCircuitsOpen = false;
if (!chain.length) {
  allCircuitsOpen = true;
  chain = order.map(p => ({ provider: p, model: config.models[p] }));
}

return [{
  json: {
    requestId: req.requestId,
    request: req,
    config,
    promptHash: base.promptHash,
    startedAt: base.startedAt,
    primaryProvider: order[0],
    chain,
    skipped,
    allCircuitsOpen,
    providerIndex: 0,
    attemptOnProvider: 0,
    totalAttempts: 0,
    repairHint: '',
    attempts: []
  }
}];

const s = $input.first().json;
const step = s.chain[s.providerIndex];
const r = s.request;

const userPrompt = s.repairHint ? r.prompt + '\n\n' + s.repairHint : r.prompt;
let system = r.systemPrompt;
if (r.expectJson && !/json/i.test(system)) system += '\nReturn ONLY a valid JSON object. No markdown fences, no commentary.';

let reqBody;
if (step.provider === 'anthropic') {
  reqBody = {
    model: step.model, max_tokens: r.maxTokens, temperature: r.temperature, system,
    messages: [{ role: 'user', content: userPrompt }]
  };
} else if (step.provider === 'openai') {
  reqBody = {
    model: step.model, max_tokens: r.maxTokens, temperature: r.temperature,
    messages: [{ role: 'system', content: system }, { role: 'user', content: userPrompt }]
  };
  if (r.expectJson) reqBody.response_format = { type: 'json_object' };
} else {
  reqBody = {
    systemInstruction: { parts: [{ text: system }] },
    contents: [{ role: 'user', parts: [{ text: userPrompt }] }],
    generationConfig: { maxOutputTokens: r.maxTokens, temperature: r.temperature }
  };
  if (r.expectJson) reqBody.generationConfig.responseMimeType = 'application/json';
  // Gemini 2.5 Flash "thinking" tokens count against maxOutputTokens, so disable them to avoid truncation
  if (/2\.5-flash/.test(step.model)) reqBody.generationConfig.thinkingConfig = { thinkingBudget: 0 };
}

return [{
  json: {
    ...s,
    provider: step.provider,
    model: step.model,
    attemptOnProvider: s.attemptOnProvider + 1,
    totalAttempts: s.totalAttempts + 1,
    attemptStartedAt: Date.now(),
    reqBody
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const s = ref('JS - Select Provider');
const resp = $input.first().json;
const r = s.request, cfg = s.config;
const latencyMs = Date.now() - s.attemptStartedAt;

const statusCode = Number(resp.statusCode) || 0;
let body = resp.body;
if (typeof body === 'string') { try { body = JSON.parse(body); } catch (e) { body = {}; } }
if (!body || typeof body !== 'object') body = {};

// ---- 1. Extract text / usage per provider ----
let text = '', finishReason = '', inTok = null, outTok = null, providerError = '', refusalFlag = false;
if (s.provider === 'anthropic') {
  const block = (body.content || []).find(b => b.type === 'text');
  text = block ? block.text : '';
  finishReason = body.stop_reason || '';
  inTok = body.usage?.input_tokens ?? null;
  outTok = body.usage?.output_tokens ?? null;
  providerError = body.error?.message || '';
  if (finishReason === 'refusal') refusalFlag = true;
} else if (s.provider === 'openai') {
  const c = (body.choices || [])[0] || {};
  text = c.message?.content || '';
  finishReason = c.finish_reason || '';
  inTok = body.usage?.prompt_tokens ?? null;
  outTok = body.usage?.completion_tokens ?? null;
  providerError = body.error?.message || '';
  if (c.message?.refusal) refusalFlag = true;
} else {
  const c = (body.candidates || [])[0] || {};
  text = (c.content?.parts || []).map(p => p.text || '').join('');
  finishReason = c.finishReason || (body.promptFeedback?.blockReason ? 'BLOCKED_' + body.promptFeedback.blockReason : '');
  inTok = body.usageMetadata?.promptTokenCount ?? null;
  outTok = body.usageMetadata?.candidatesTokenCount ?? null;
  providerError = body.error?.message || '';
}

// ---- 2. Classify transport / HTTP errors ----
const issues = [];
let errorType = null, retryable = false, retryAfterMs = 0;
const ra = resp.headers ? resp.headers['retry-after'] : null;
if (ra && isFinite(Number(ra))) retryAfterMs = Number(ra) * 1000;

if (resp.error && !statusCode) {
  const em = typeof resp.error === 'string' ? resp.error : (resp.error.message || 'unknown error');
  errorType = 'network_or_timeout'; retryable = true;
  issues.push('Request failed: ' + String(em).slice(0, 200));
} else if (statusCode === 429) {
  errorType = 'rate_limited'; retryable = true;
} else if (statusCode === 408 || statusCode >= 500) {
  errorType = 'provider_error'; retryable = true;
} else if (statusCode >= 400) {
  errorType = 'client_error'; retryable = false;
} else if (statusCode === 0) {
  errorType = 'network_or_timeout'; retryable = true;
  issues.push('No HTTP status returned');
}
if (errorType) {
  issues.push('HTTP ' + statusCode + (providerError ? ': ' + String(providerError).slice(0, 200) : ''));
}

// ---- 3. Validate the response content (deterministic) ----
function extractJson(t) {
  const cleaned = t.replace(/```json|```/gi, '').trim();
  try { return JSON.parse(cleaned); } catch (e) {}
  const a = cleaned.indexOf('{'), b = cleaned.lastIndexOf('}');
  if (a !== -1 && b > a) { try { return JSON.parse(cleaned.slice(a, b + 1)); } catch (e) {} }
  return null;
}

let parsed = null;
if (!errorType) {
  const t = (text || '').trim();
  if (/^(length|max_tokens|MAX_TOKENS)$/.test(finishReason)) issues.push('Response truncated (finish reason: ' + finishReason + ')');
  if (/^(content_filter|SAFETY|RECITATION|PROHIBITED_CONTENT|BLOCKLIST|SPII)$/i.test(finishReason) || finishReason.startsWith('BLOCKED_')) {
    issues.push('Response blocked by provider safety filter (' + finishReason + ')');
  }
  if (cfg.rejectRefusals && refusalFlag) issues.push('Provider reported a refusal');

  if (!t) {
    issues.push('Empty response');
  } else {
    if (t.length < r.minChars) issues.push('Response shorter than ' + r.minChars + ' characters');
    if (t.length > r.maxChars) issues.push('Response longer than ' + r.maxChars + ' characters');
    if (cfg.rejectRefusals && /^\s*(i['’]m sorry,? but |sorry,? but |i am sorry,? but )?i (can(?:not|['’]t)|am (?:unable|not able) to) (help|assist|comply|provide|fulfil)/i.test(t)) {
      issues.push('Response looks like a refusal');
    }
    const lower = t.toLowerCase();
    for (const kw of r.mustContain) if (!lower.includes(kw.toLowerCase())) issues.push('Missing required text: ' + kw);
    for (const kw of r.mustNotContain) if (lower.includes(kw.toLowerCase())) issues.push('Contains forbidden text: ' + kw);

    if (r.expectJson) {
      parsed = extractJson(t);
      if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
        issues.push('Response is not a valid JSON object');
        parsed = null;
      } else {
        for (const [key, rule] of Object.entries(r.schema || {})) {
          const v = parsed[key];
          if (v === undefined || v === null) { issues.push('Missing required key: ' + key); continue; }
          const rl = String(rule);
          if (rl.startsWith('enum:')) {
            const allowed = rl.slice(5).split('|');
            if (!allowed.includes(String(v))) issues.push('Key "' + key + '" must be one of ' + allowed.join('/'));
          } else {
            const type = Array.isArray(v) ? 'array' : typeof v;
            if (type !== rl) issues.push('Key "' + key + '" must be of type ' + rl);
            else if (rl === 'string' && !String(v).trim()) issues.push('Key "' + key + '" must not be empty');
          }
        }
      }
    }
  }
}

const valid = !errorType && issues.length === 0;
const failureKind = errorType || (valid ? null : 'invalid_output');

const attempt = {
  attemptNo: s.totalAttempts, provider: s.provider, model: s.model, success: valid,
  statusCode, errorType: failureKind, issues, latencyMs,
  inputTokens: inTok, outputTokens: outTok, responseChars: (text || '').length, finishReason
};

const { reqBody, ...rest } = s;
return [{
  json: {
    ...rest,
    attempts: [...s.attempts, attempt],
    lastAttempt: attempt,
    valid,
    errorType: failureKind,
    retryable: errorType ? retryable : true,
    retryAfterMs,
    issues,
    text: valid ? text.trim() : '',
    parsed: valid ? parsed : null
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
// The Postgres node replaces the item with its query result, so put the full state back.
return [{ json: ref('JS - Normalize & Validate') }];

const s = $input.first().json;
const totalLatencyMs = Date.now() - s.startedAt;
const fallbackUsed = s.provider !== s.primaryProvider;
const status = fallbackUsed ? 'success_after_fallback' : 'success';
const trace = s.attempts.map(a => ({
  attempt: a.attemptNo, provider: a.provider, model: a.model, success: a.success,
  error: a.errorType, statusCode: a.statusCode, latencyMs: a.latencyMs, issues: a.issues
}));

const response = {
  requestId: s.requestId, status, provider: s.provider, model: s.model,
  text: s.text, parsed: s.parsed, stale: false, fallbackUsed,
  attemptCount: s.attempts.length, totalLatencyMs, skippedProviders: s.skipped, trace
};

return [{
  json: {
    requestId: s.requestId, status, provider: s.provider, model: s.model, fallbackUsed,
    attemptCount: s.attempts.length, totalLatencyMs, promptHash: s.promptHash,
    cacheText: s.text, httpStatus: 200, response, config: s.config
  }
}];

const s = $input.first().json;
const cfg = s.config;

let providerIndex = s.providerIndex;
let attemptOnProvider = s.attemptOnProvider;
let repairHint = '';
let backoffSeconds = 0;
let action;

// A long rate-limit window is not worth waiting for: switch provider instead.
const longRateLimit = s.errorType === 'rate_limited' && (s.retryAfterMs / 1000) > cfg.maxBackoffSeconds;
const canRetrySame = s.retryable && !longRateLimit && s.attemptOnProvider < cfg.maxAttemptsPerProvider;

if (canRetrySame) {
  action = 'retry_same_provider';
  if (s.errorType === 'invalid_output') {
    // Repair retry: tell the model exactly what was wrong with its last answer.
    repairHint = 'IMPORTANT: your previous reply was rejected for these reasons: ' + s.issues.join('; ') +
      '. Fix every problem and reply again, following the original instructions exactly.';
  } else {
    const exp = cfg.backoffBaseSeconds * Math.pow(2, s.attemptOnProvider - 1);
    const jitter = Math.random() * cfg.backoffBaseSeconds;
    backoffSeconds = Math.min(cfg.maxBackoffSeconds, Math.max(exp + jitter, s.retryAfterMs / 1000));
    backoffSeconds = Math.round(backoffSeconds * 10) / 10;
  }
} else {
  action = 'switch_provider';
  providerIndex = s.providerIndex + 1;
  attemptOnProvider = 0;
}

const exhausted = providerIndex >= s.chain.length;

return [{
  json: {
    ...s,
    providerIndex,
    attemptOnProvider,
    repairHint,
    backoffSeconds,
    nextAction: exhausted ? 'exhausted' : action,
    exhausted
  }
}];

function ref(name) { try { return $(name).item.json; } catch (e) { return $(name).first().json; } }
const s = ref('JS - Plan Next Step');
const row = $input.first().json;
const cached = (row && row.response_text) ? row : null;
const totalLatencyMs = Date.now() - s.startedAt;

let status, text, parsed = null, httpStatus, provider, model = null, extra = {};
if (cached) {
  status = 'degraded_cached';
  httpStatus = 200;
  text = cached.response_text;
  provider = 'stale_cache';
  model = cached.model || null;
  extra = { originalProvider: cached.provider, cachedAt: cached.created_at };
  if (s.request.expectJson) {
    try { parsed = JSON.parse(text.replace(/```json|```/gi, '').trim()); } catch (e) { parsed = null; }
  }
} else {
  status = 'degraded_static';
  httpStatus = 503;
  text = s.config.degradedMessage;
  provider = 'none';
}

const trace = s.attempts.map(a => ({
  attempt: a.attemptNo, provider: a.provider, model: a.model, success: a.success,
  error: a.errorType, statusCode: a.statusCode, latencyMs: a.latencyMs, issues: a.issues
}));

const response = {
  requestId: s.requestId, status, provider, model, text, parsed, stale: !!cached,
  fallbackUsed: true, attemptCount: s.attempts.length, totalLatencyMs,
  skippedProviders: s.skipped, trace, ...extra
};

return [{
  json: {
    requestId: s.requestId, status, provider, model, fallbackUsed: true,
    attemptCount: s.attempts.length, totalLatencyMs, promptHash: s.promptHash,
    cacheText: null, // never store degraded output as cache text
    httpStatus, response, config: s.config
  }
}];

function tryRef(n) {
  try { const x = $(n).first().json; return (x && x.requestId) ? x : null; } catch (e) { return null; }
}
// Only one of the two builders ran in this execution.
const r = tryRef('JS - Build Success Response') || tryRef('JS - Build Degraded Response');
if (!r) throw new Error('No final response was built');

const saved = $input.first().json;
const alertNeeded = r.fallbackUsed === true || String(r.status).startsWith('degraded');

return [{ json: { ...r, alertNeeded, persisted: !!(saved && saved.request_id) } }];

